{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace table PEESAFE_DB.MAPLEMONK.RFM_SCORE ( \"Lower Limit\" FLOAT,\"Upper Limit\" FLOAT,Score FLOAT); Insert into PEESAFE_DB.MAPLEMONK.RFM_SCORE values (0,0.1,10), (0.1,0.2,9), (0.2,0.3,8),(0.3,0.4,7),(0.4,0.5,6),(0.5,0.6,5),(0.6,0.7,4),(0.7,0.8,3),(0.8,0.9,2),(0.9,1,1); CREATE or replace TABLE PEESAFE_DB.MAPLEMONK.RFM_CUSTOMER_CATEGORY_MAPPING ( R_Start FLOAT,R_End FLOAT,F_Start FLOAT,F_End FLOAT,M_Start FLOAT,M_End FLOAT, Category VARCHAR(16777216)); Insert into PEESAFE_DB.MAPLEMONK.rfm_customer_category_mapping values (8,10,8,10,6,10,\'Champion\') ,(8,10,8,10,4,6,\'Frequent Customer with medium spend\') ,(8,10,8,10,0,4,\'Frequent Customer with low spend\') ,(6,8,8,10,0,10,\'Loyal Customers\') ,(8,10,6,8,0,10,\'Loyal Customers\') ,(4,6,0,6,0,10,\'Potential to become inactive\') ,(0,4,4,6,0,10,\'Potential to become inactive\') ,(6,8,6,8,0,10,\'Potential to become loyal Customers\') ,(8,10,4,6,0,10,\'Needs more engagement\') ,(6,8,0,6,0,10,\'Needs more engagement\') ,(8,10,0,4,0,10,\'New Customer/Promising Customers\') ,(0,6,6,10,0,10,\'Initiate re-engagement\') ,(0,4,0,4,0,10,\'Inactive Customers\'); create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase_intermediate as select last_product, next_product, number, list, share from( select *, row_number() over (partition by last_product order by number desc) list, number/sum(number) over (partition by last_product) Share from ( select b.product_name last_product, a.product_name next_product, count(*) number from ( select row_number() over (partition by customer_id_final order by order_id) order_number,* from ( select dense_rank() over (partition by order_id order by selling_price,product_id desc) rw, * from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated where lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') and right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) != \'9999999999\' ) where rw = 1 ) a left join ( select distinct customer_id_final , order_number, product_name from ( select row_number() over (partition by customer_id_final order by order_id) order_number,* from ( select dense_rank() over (partition by order_id order by selling_price,product_id desc) rw, * from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated where lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') and right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) != \'9999999999\' ) where rw = 1 ) ) b on a.order_number = (b.order_number + 1) and a.customer_id_final = b.customer_id_final where b.order_number is not null and b.customer_id_final is not null and a.product_name NOT LIKE \'%🎁%\' group by b.product_name, a.product_name order by 3 desc ) ) where list in (1,2,3); create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase as select a.last_product, next_product1, next_product2, next_product3, share1, share2, share3 from (select last_product , next_product as next_product1 , share as share1 from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase_intermediate where list = 1 ) a left join (select last_product ,next_product as next_product2 ,share as share2 from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase_intermediate where list = 2 ) b on a.last_product = b.last_product left join (select last_product ,next_product as next_product3 ,share as share3 from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase_intermediate where list = 3 ) c on a.last_product = c.last_product ; create or replace table PEESAFE_DB.MAPLEMONK.customer_master_intermediate as with valid_sales as ( select * from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_SALES_CONSOLIDATED where right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) != \'9999999999\' and customer_id_final is not null and order_date is not null ), first_purchase as ( select customer_id_final, order_date as acquisition_date, shop_name as acquisition_marketplace, source as acquisition_marketing_channel, product_name as acquisition_product from ( select customer_id_final, order_date, order_id, shop_name, source, product_name, selling_price, product_id, row_number() over ( partition by customer_id_final order by order_date asc, order_id asc, selling_price desc, product_id desc ) as rn from valid_sales where product_name not like \'%🎁%\' ) where rn = 1 ), max_order as ( select customer_id_final, max(order_date) as max_order_date from valid_sales group by customer_id_final ) select fi.customer_id_final as MM_Customer_ID, max(fi.name) as Name, max(fi.email) as Email, fi.phone as Phone, fp.acquisition_date as Acquisition_Date, fp.acquisition_marketplace as Acquistion_Marketplace, fp.acquisition_marketing_channel as Acquisition_Marketing_Channel, fp.acquisition_product as Acquisition_Product, datediff(day,min(fi.order_date),current_date) as Days_Since_First_Purchase, max(case when fi.order_date = mo.max_order_date then fi.product_name end) as Last_Product, ifnull(sum(fi.selling_price),0) as Total_Sales_INR, count(distinct fi.order_id) as Total_Orders, count(distinct case when lower(fi.order_status) in (\'cancelled\',\'returned\',\'rto\') then fi.order_id end) as Cancelled_Orders, count(distinct case when lower(fi.order_status) in (\'returned\',\'rto\') then fi.order_id end) as Returned_Orders, count(distinct case when lower(fi.shop_name) like \'%shopify%\' then fi.order_id end) as Total_Shopify_Orders, count(distinct case when lower(fi.shop_name) like \'%cred%\' then fi.order_id end) as Total_CRED_Orders, count(distinct fi.saleorderitemcode) as Total_Items, max(case when fi.order_date = mo.max_order_date then fi.order_id end) as Last_Order_Id, datediff(day,max(fi.order_date),current_date) as Days_Since_Last_Purchase, case when count(distinct fi.order_id) = 0 then null else datediff(day,min(fi.order_date),max(fi.order_date)) / count(distinct fi.order_id) end as Avg_days_between_purchases, sum(fi.discount) as discount_inr, case when sum(fi.selling_price) = 0 then null else sum(fi.discount) / sum(fi.selling_price) end as discount_percent, sum(ifnull(fi.days_in_shipment,0)) as days_in_shipment from valid_sales fi left join first_purchase fp on fi.customer_id_final = fp.customer_id_final left join max_order mo on fi.customer_id_final = mo.customer_id_final group by fi.customer_id_final, fi.phone, fp.acquisition_date, fp.acquisition_marketplace, fp.acquisition_marketing_channel, fp.acquisition_product; create or replace table PEESAFE_DB.MAPLEMONK.peesafe_db_customer_master as select x.*, np.next_product1, np.next_product2, np.next_product3, np.share1, np.share2, np.share3, rcm.Category as Customer_Segment from ( select c.*, m.Score as M_Score, r.Score as R_Score, f.Score as F_Score, (r.Score*1/3 + f.Score*1/3 + m.Score*1/3) as RFM_Score from ( select *, row_number() over ( order by TOTAL_Sales_INR desc ) / ( select count(distinct MM_CUSTOMER_ID) from PEESAFE_DB.MAPLEMONK.Customer_Master_Intermediate ) as Percentile_M, row_number() over ( order by DAYS_SINCE_LAST_PURCHASE asc, MM_CUSTOMER_ID ) / ( select count(distinct MM_CUSTOMER_ID) from PEESAFE_DB.MAPLEMONK.Customer_Master_Intermediate ) as Percentile_R, case when AVG_DAYS_BETWEEN_PURCHASES = 0 then 0.4 else row_number() over ( partition by case when AVG_DAYS_BETWEEN_PURCHASES = 0 then 0 else 1 end order by AVG_DAYS_BETWEEN_PURCHASES asc, MM_CUSTOMER_ID ) / ( select count(distinct MM_CUSTOMER_ID) from PEESAFE_DB.MAPLEMONK.Customer_Master_Intermediate ) end as Percentile_F from PEESAFE_DB.MAPLEMONK.Customer_Master_Intermediate ) c left join PEESAFE_DB.MAPLEMONK.RFM_Score m on c.Percentile_M > m.\"Lower Limit\" and c.Percentile_M <= m.\"Upper Limit\" left join PEESAFE_DB.MAPLEMONK.RFM_Score r on c.Percentile_R > r.\"Lower Limit\" and c.Percentile_R <= r.\"Upper Limit\" left join PEESAFE_DB.MAPLEMONK.RFM_Score f on c.Percentile_F > f.\"Lower Limit\" and c.Percentile_F <= f.\"Upper Limit\" ) x left join PEESAFE_DB.MAPLEMONK.RFM_CUSTOMER_CATEGORY_MAPPING rcm on x.M_Score::int > rcm.\"M_START\"::int and x.M_Score::int <= rcm.\"M_END\"::int and x.R_Score::int > rcm.\"R_START\"::int and x.R_Score::int <= rcm.\"R_END\"::int and x.F_Score::int > rcm.\"F_START\"::int and x.F_Score::int <= rcm.\"F_END\"::int left join PEESAFE_DB.MAPLEMONK.PEESAFE_DB_next_purchase np on np.last_product = x.last_product;",
                    "transaction": true
                }
            ) }}
